\documentclass[border=5mm]{standalone}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{calc, arrows, intersections, fillbetween}

\begin{document}

\pagestyle{empty}

% Colors
\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\newcommand{\mydot}[2]{
    \node[circle, draw=none, fill=#2, inner sep=1.5pt] at (axis cs:#1) {};
}

\begin{tikzpicture}[declare function={f(\x)=0.667*\x+1/3;}]

\begin{axis}[
clip=false,
enlargelimits=false,
tick label style={font=\footnotesize},
label style={font=\small},
tick style={draw=black,thick}, minor tick style={draw=none},
axis line style = thick,
axis y line = middle, axis x line = middle,
%axis equal,
grid = both, grid style={thin, color=lightgray!50},
xmin = 0, xmax = 8.75,
%axis x discontinuity=crunch, %crunch|parallel|none
ymin = 0, ymax = 8.75,
%axis y discontinuity=crunch, %crunch|parallel|none
xtick = {0,1,...,8}, xticklabels = {0,10,...,80},
ytick = {0,2,...,12}, yticklabels = {0,2,...,12},
minor xtick={0,1,...,10},
minor ytick={0,1,...,10},   
xlabel = {$x$}, ylabel = {$y$},
x label style={right=4pt},
y label style={above=4pt},
]

% Random seed
\pgfmathsetseed{1}

% Closer to 0 -> more linear 
\def\spread{0.85}

% Trend Line
\plot[domain=0.5:8.5, variable=\x, orangepeel, very thick]{f(\x)};

% Blob
\foreach \x [evaluate=\x as \y using f(\x)] in {0.6,0.75,...,8.5}{
	\edef\temp{
		\noexpand
		\node[circle, draw=none, fill=deepskyblue, inner sep=1.5pt,fill opacity=0.25] at (axis cs: \x, \y+rand*\spread) {};
	}\temp
}

\node[circle, inner sep=2pt, draw=none, fill=fadedpink] at (axis cs:7,0) {};
\draw[->, thick, fadedpink, shorten <                  = 5pt, shorten > = 1pt] (axis cs:7,0) -- (axis cs:7,5);

\end{axis}

\end{tikzpicture}
\end{document}

